--
-- Table structure for table `dataset_dataelement_settings`
--

DROP TABLE IF EXISTS `dataset_dataelement_settings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dataset_dataelement_settings` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `survey_id` int NOT NULL,
  `data_element_id` varchar(11) NOT NULL,
  `data_element_name` varchar(255) NOT NULL,
  `data_element_code` varchar(50) DEFAULT NULL,
  `section_id` varchar(11) DEFAULT NULL,
  `section_name` varchar(255) DEFAULT NULL,
  `display_order` int DEFAULT '0',
  `is_visible` tinyint(1) DEFAULT '1',
  `is_required` tinyint(1) DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_survey_element` (`survey_id`,`data_element_id`),
  KEY `idx_survey_order` (`survey_id`,`display_order`),
  KEY `idx_section` (`survey_id`,`section_id`),
  CONSTRAINT `dataset_dataelement_settings_ibfk_1` FOREIGN KEY (`survey_id`) REFERENCES `survey` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

