--
-- Table structure for table `dataset_layout_settings`
--

DROP TABLE IF EXISTS `dataset_layout_settings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dataset_layout_settings` (
  `id` int NOT NULL AUTO_INCREMENT,
  `survey_id` int NOT NULL,
  `layout_type` enum('horizontal','vertical') DEFAULT 'horizontal' COMMENT 'Image layout type',
  `show_facility_section` tinyint(1) DEFAULT '1',
  `selected_instance_key` varchar(64) DEFAULT NULL,
  `selected_hierarchy_level` int DEFAULT NULL,
  `show_flag_bar` tinyint(1) DEFAULT '1' COMMENT 'Show Uganda flag bar',
  `flag_black_color` varchar(7) DEFAULT '#000000',
  `flag_yellow_color` varchar(7) DEFAULT '#FCD116',
  `flag_red_color` varchar(7) DEFAULT '#D21034',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `use_direct_orgunits` tinyint(1) DEFAULT '1',
  `form_type` varchar(20) DEFAULT 'DEFAULT',
  `cache_dataset_metadata` tinyint(1) DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `survey_id_unique` (`survey_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
