DROP TABLE IF EXISTS `dataset_metadata`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dataset_metadata` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `survey_id` int NOT NULL,
  `dataset_uid` varchar(11) COLLATE utf8mb4_unicode_ci NOT NULL,
  `dataset_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `dataset_display_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `dataset_description` text COLLATE utf8mb4_unicode_ci,
  `period_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Monthly',
  `form_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DEFAULT',
  `custom_form_html` longtext COLLATE utf8mb4_unicode_ci,
  `custom_form_style` text COLLATE utf8mb4_unicode_ci,
  `timely_days` int DEFAULT NULL,
  `expiry_days` int DEFAULT NULL,
  `open_future_periods` int DEFAULT NULL,
  `synced_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `survey_id` (`survey_id`),
  KEY `idx_survey_id` (`survey_id`),
  KEY `idx_dataset_uid` (`dataset_uid`),
  CONSTRAINT `dataset_metadata_ibfk_1` FOREIGN KEY (`survey_id`) REFERENCES `survey` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
