INSERT INTO `dataset_metadata` VALUES (27,16,'qXXITEiyaZj','Pre-Primary Termly Tool','Pre-Primary Termly Tool','','Yearly','CUSTOM','<style type=\"text/css\">body {font-family: \"Lato\", sans-serif;}\n\n    input.entryfield {width: 60% !important;}\n    input.indicator {width: 60% !important;}\n    input.dataelementtotal {width: 60% !important;}\n    \n    /* Style the tab */\n    \n    .tab {\n        float: left;\n        background-color:#acdf87;\n        width: 100%;\n        height: 100%;\n    }\n    \n    \n    /* Style the buttons inside the tab */\n    .tab button {\n        display: block;\n        background-color: inherit;\n        color: black;\n        padding: 5px 16px;\n        width: 100%;\n        text-align: left;\n        cursor: pointer;\n        transition: 0.3s;\n        font-size: 15px;\n        border-bottom: 1px solid #a4d2a3;\n        outline: #FFFFFF solid 1px;\n    }\n    \n    /* Change background color of buttons on hover */\n    .tab button:hover {\n        background-color: #4c9a2a;\n        color: #ffffff;\n    }\n    \n    /* Create an active/current \"tab button\" class */\n    .tab button.active {\n    \n        background-color: #4c9a2a;\n        color: #ffffff;\n        \n    }\n    \n    /* Style the tab content */\n    .tabcontent {\n        float: left;\n        padding: 0px 0px;\n        width: 100%;\n        height: 100%;\n    }\n    .section-head{\n        color: #FFFFFF;\n        font-size: 15px;\n        margin: 4px;\n        font-weight: bold;\n    }\n    .table-header{\n        color: #bddcbd;\n    }\n</style>\n<table border=\"1\" bordercolor=\"#ccc\" cellpadding=\"5\" cellspacing=\"0\" style=\"border-collapse:collapse;\" width=\"100%\">\n	<tbody>\n		<tr>\n			<td bgcolor=\"#4c9a2a\" colspan=\"2\">\n			<p><span style=\"font-size:20px;color:#fdfcfc;\"><strong>PRE-PRIMARY SCHOOL TERMLY DATA REPORTING FORM</strong></span></p>\n			</td>\n		</tr>\n		<tr>\n			<td valign=\"top\" width=\"20%\">\n			<div class=\"tab\"><button class=\"tablinks\" id=\"button1\" onclick=\"opentab(event, \'tab1\')\">SECTION A: Background Information</button><button class=\"tablinks\" id=\"button2\" onclick=\"opentab(event, \'tab2\')\">SECTION A1: Background Information</button><button class=\"tablinks\" id=\"button3\" onclick=\"opentab(event, \'tab3\')\">SECTION B: Learners&#39; Information</button><button class=\"tablinks\" id=\"button4\" onclick=\"opentab(event, \'tab4\')\">SECTION C: Enrolment of Children with Special Needs</button><button class=\"tablinks\" id=\"button5\" onclick=\"opentab(event, \'tab5\')\">SECTION D: Number of orphans</button><button class=\"tablinks\" id=\"button6\" onclick=\"opentab(event, \'tab6\')\">SECTION E: Number of non-Ugandan learners</button><button class=\"tablinks\" id=\"button7\" onclick=\"opentab(event, \'tab7\')\">SECTION F: Staff information</button><button class=\"tablinks\" id=\"button8\" onclick=\"opentab(event, \'tab8\')\">SECTION F1: Staff information</button><button class=\"tablinks\" id=\"button9\" onclick=\"opentab(event, \'tab9\')\">SECTION G: Infrastructure</button><button class=\"tablinks\" id=\"button10\" onclick=\"opentab(event, \'tab10\')\">SECTION H: Sanitation Facilities</button><button class=\"tablinks\" id=\"button11\" onclick=\"opentab(event, \'tab11\')\">SECTION H1: Safe and Secure Environment Information in the reporting term</button><button class=\"tablinks\" id=\"button12\" onclick=\"opentab(event, \'tab12\')\">SECTION I: Learning and Playing Materials</button><button class=\"tablinks\" id=\"button13\" onclick=\"opentab(event, \'tab13\')\">SECTION J1: Integrated Health Services</button><button class=\"tablinks\" id=\"button14\" onclick=\"opentab(event, \'tab14\')\">SECTION J: Integrated Health Services</button><button class=\"tablinks\" id=\"button15\" onclick=\"opentab(event, \'tab15\')\">SECTION K: School feeding</button><button class=\"tablinks\" id=\"button16\" onclick=\"opentab(event, \'tab16\')\">SECTION L1: Centre Governance</button><button class=\"tablinks\" id=\"button17\" onclick=\"opentab(event, \'tab17\')\">SECTION L: Centre Governance</button><button class=\"tablinks\" id=\"button18\" onclick=\"opentab(event, \'tab18\')\">SECTION M: Number of learners absent in the reporting school term</button><button class=\"tablinks\" id=\"button19\" onclick=\"opentab(event, \'tab19\')\">SECTION N: Number of teachers absent in the reporting school term</button></div>\n			</td>\n			<td style=\"background-color: #e9f3e9;\" valign=\"top\">\n			<div class=\"tabcontent\" id=\"tab1\">\n			<p><strong>A: Background Information</strong></p>\n\n			<table border=\"1\" cellpadding=\"1\" cellspacing=\"1\" height=\"369\" width=\"1051\">\n				<tbody>\n					<tr>\n						<td colspan=\"6\" style=\"background-color:#bddcbd;\"><strong>SECTION A: Background Information</strong></td>\n					</tr>\n					<tr>\n						<td colspan=\"3\">A6. EMIS No</td>\n						<td colspan=\"3\"><input id=\"QWJujQPSsR9-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n					</tr>\n					<tr>\n						<td colspan=\"3\">A7. School Email address</td>\n						<td colspan=\"3\"><input id=\"LgDEQNEZbow-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n					</tr>\n					<tr>\n						<td colspan=\"3\">A8. School contact</td>\n						<td colspan=\"3\"><input id=\"ppbxbQDpZdw-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n					</tr>\n					<tr>\n						<td colspan=\"3\">A9. Head teacher contact</td>\n						<td colspan=\"3\"><input id=\"jNWoGjCF5qC-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n					</tr>\n					<tr>\n					</tr>\n				</tbody>\n			</table>\n			</div>\n\n			<div class=\"tabcontent\" id=\"tab2\">\n			<p><strong>A1: Background Information</strong></p>\n\n			<table border=\"1\" cellpadding=\"1\" cellspacing=\"1\" height=\"369\" width=\"1051\">\n				<tbody>\n					<tr>\n						<td colspan=\"6\" style=\"background-color:#bddcbd;\"><strong>SECTION A1: Background Information</strong></td>\n					</tr>\n					<tr>\n						<td colspan=\"6\">A12. Is the ECCE centre a Day Care Centre, Nursery or both?</td>\n					</tr>\n					<tr>\n						<td>Day Care only</td>\n						<td><input id=\"oipBSL0sS2c-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n						<td>Nursery only</td>\n						<td><input id=\"Oo2nHFzJ3fQ-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n						<td>Nursery and Day care</td>\n						<td><input id=\"f03lAr3QmeY-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n					</tr>\n					<tr>\n						<td>Home based</td>\n						<td><input id=\"nyBlfmsu7NM-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n						<td>Community based</td>\n						<td><input id=\"g8wHZEaUKzt-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n						<td>Others</td>\n						<td><input id=\"ImPMAmhDwbm-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n					</tr>\n					<tr>\n						<td colspan=\"3\">A13. Is the centre attached to a primary school?</td>\n						<td colspan=\"3\"><input id=\"QuSztXmx3uY-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n					</tr>\n					<tr>\n						<td colspan=\"6\">A14. Who founded this ECCE Centre?</td>\n					</tr>\n					<tr>\n						<td>Entrepreneurs</td>\n						<td><input id=\"HqwjYNfnrwk-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n						<td>Islamic</td>\n						<td><input id=\"maED3QHxIej-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n						<td>Community</td>\n						<td><input id=\"k6SQT6NBm99-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n					</tr>\n					<tr>\n						<td>COU/Anglican</td>\n						<td><input id=\"DqXMqLrKgTB-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n						<td>SDA</td>\n						<td><input id=\"NpSEA2cbJzr-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n						<td>CBOs / NGOs</td>\n						<td><input id=\"SqNwu1SKISL-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n					</tr>\n					<tr>\n						<td>Roman Catholic</td>\n						<td><input id=\"Bux91prT9hu-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n						<td>Orthodox</td>\n						<td><input id=\"yJYlgh8098Z-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n						<td>Others</td>\n						<td><input id=\"NGzBzNWQ2sA-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n					</tr>\n					<tr>\n						<td colspan=\"5\" rowspan=\"1\">A15. In what year was this school founded ?</td>\n						<td><input id=\"joyHVNZrNys-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n					</tr>\n					<tr>\n						<td colspan=\"6\">A16. Location of the ECCE Centre</td>\n					</tr>\n					<tr>\n						<td>Urban</td>\n						<td><input id=\"hFBVRlZjMv2-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n						<td>Peri-urban</td>\n						<td><input id=\"kZAiVx41pjw-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n						<td>Rural</td>\n						<td><input id=\"x7opXh1sOEH-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n					</tr>\n					<tr>\n						<td colspan=\"6\">A17. What is the licensing or registration status of this ECCE Centre?</td>\n					</tr>\n					<tr>\n						<td colspan=\"2\">Licensed</td>\n						<td><input id=\"A3NasjSTdun-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n						<td colspan=\"2\">Registered</td>\n						<td><input id=\"ZkoBHpyAnln-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n					</tr>\n					<tr>\n						<td colspan=\"5\" rowspan=\"1\">A18. If licensed, What is the licensing number ?</td>\n						<td><input id=\"kIIRYsAuoiu-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n					</tr>\n					<tr>\n						<td colspan=\"5\">A19.If Registered, What is the registration number ?</td>\n						<td><input id=\"IKLxnLu1JiS-HllvX50cXC0-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n					</tr>\n				</tbody>\n			</table>\n			</div>\n\n			<div class=\"tabcontent\" id=\"tab3\">\n			<p><strong>B: LEARNERS&#39; INFORMATION</strong></p>\n\n			<table border=\"1\" cellpadding=\"1\" cellspacing=\"1\" height=\"369\" width=\"1051\">\n				<tbody>\n					<tr>\n						<td colspan=\"9\" style=\"background-color:#bddcbd;\"><strong>SECTION B: Learners&#39; Information</strong></td>\n					</tr>\n					<tr>\n						<td colspan=\"9\">What is the total number of learners by sex and age per class in the reporting term?</td>\n					</tr>\n					<tr style=\"background-color:#bddcbd;\">\n						<td>&nbsp;</td>\n						<td colspan=\"2\" style=\"text-align: center;\"><strong>Day Care Centre</strong></td>\n						<td colspan=\"2\" style=\"text-align: center;\"><strong>Baby Class</strong></td>\n						<td colspan=\"2\" style=\"text-align: center;\"><strong>Middle Class</strong></td>\n						<td colspan=\"2\" style=\"text-align: center;\"><strong>Top Class</strong></td>\n					</tr>\n					<tr style=\"background-color:#bddcbd;\">\n						<td>&nbsp;</td>\n						<td style=\"text-align: center;\"><strong>Boys</strong></td>\n						<td style=\"text-align: center;\"><strong>Girls</strong></td>\n						<td style=\"text-align: center;\"><strong>Boys</strong></td>\n						<td style=\"text-align: center;\"><strong>Girls</strong></td>\n						<td style=\"text-align: center;\"><strong>Boys</strong></td>\n						<td style=\"text-align: center;\"><strong>Girls</strong></td>\n						<td style=\"text-align: center;\"><strong>Boys</strong></td>\n						<td style=\"text-align: center;\"><strong>Girls</strong></td>\n					</tr>\n					<tr>\n						<td><strong>&lt;3 years</strong></td>\n						<td><input id=\"uonYnRkqoIs-kED3MF1c6Ar-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n						<td><input id=\"uonYnRkqoIs-AeCn0VYlGO9-val\" name=\"entryfield\" title=\"\" value=\"\" /></td>\n						<td><input id=\"uonYnRkqoIs-cVH6IvQ921V-val\" name=\"entryfield\" 