 \"tab20\");\n			toggleTab(defaultTerm, disableButton, \"tab22\");\n			toggleTab(defaultTerm, disableButton, \"tab23\");\n           \n\n			console.log(\'Selected term has changed to: \' + defaultTerm);\n			// On change\n			term.addEventListener(\'change\', function () {\n				var selectedTerm = term.options[term.selectedIndex].value;\n				toggleTab(selectedTerm, disableButton, \"tab2\");\n				toggleTab(selectedTerm, disableButton, \"tab11\");\n				toggleTab(selectedTerm, disableButton, \"tab12\");\n				toggleTab(selectedTerm, disableButton, \"tab13\");\n				toggleTab(selectedTerm, disableButton, \"tab14\");\n				toggleTab(selectedTerm, disableButton, \"tab16\");\n				toggleTab(selectedTerm, disableButton, \"tab17\");\n				toggleTab(selectedTerm, disableButton, \"tab20\");\n				toggleTab(selectedTerm, disableButton, \"tab22\");\n				toggleTab(selectedTerm, disableButton, \"tab23\");\n               \n\n				console.log(\'Selected term has changed to: \' + selectedTerm);\n			});\n		} else {\n			console.error(\'Element for term selection not found\');\n		}\n	}\n\n	function toggleTab(selectedValue, tabButton, tabContentId) {\n		var tabContent = document.getElementById(tabContentId);  // Get the tab content by its unique ID\n		if (selectedValue === \'sJVWo7qU0uJ\') {  // Replace with the value for \"Term 3\"\n			tabButton.disabled = false;  // Enable the tab\n			if (tabContent) {\n				tabContent.style.pointerEvents = \"auto\";\n				tabContent.style.opacity = \"1\";\n			}\n		} else {\n			tabButton.disabled = false;  // Disable the tab //TODO: Set to true if you want to disable the button\n			if (tabContent) {\n				tabContent.style.pointerEvents = \"none\";\n				tabContent.style.opacity = \"0.4\";\n			}\n		}\n	}\n	// Get the element with id=\"defaultOpen\" and click on it\n\n	// document.getElementById(\"defaultOpen\").click();\n	document.querySelector(\".defaultOpen\").click();\n\n	trackTermSelection();\n\n</script>\n\n<p>&nbsp;</p>\n','NORMAL',15,0,1,'2026-01-22 15:23:33'