--
-- Table structure for table `question_group_assignments`
--

DROP TABLE IF EXISTS `question_group_assignments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `question_group_assignments` (
  `id` int NOT NULL AUTO_INCREMENT,
  `group_id` int NOT NULL,
  `question_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'DHIS2 data element ID',
  `question_order` int DEFAULT '0' COMMENT 'Order of questions within the group',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_group_question` (`group_id`,`question_id`),
  KEY `idx_group_id` (`group_id`),
  KEY `idx_question_id` (`question_id`),
  CONSTRAINT `fk_assignments_group` FOREIGN KEY (`group_id`) REFERENCES `question_groups` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2206 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

