DROP TABLE IF EXISTS `tracker_images`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tracker_images` (
  `id` int NOT NULL AUTO_INCREMENT,
  `survey_id` int NOT NULL,
  `image_order` int NOT NULL DEFAULT '1',
  `image_path` varchar(500) DEFAULT NULL,
  `image_alt_text` varchar(255) DEFAULT NULL,
  `width_px` int DEFAULT '100',
  `height_px` int DEFAULT '60',
  `position_type` enum('left','center','right') DEFAULT 'center',
  `is_active` tinyint(1) DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_survey_order` (`survey_id`,`image_order`),
  KEY `idx_survey_active` (`survey_id`,`is_active`,`image_order`),
  CONSTRAINT `tracker_images_ibfk_1` FOREIGN KEY (`survey_id`) REFERENCES `survey` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=88 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
